import {scanSource,scanDependencies,isOutdated,releaseGate,supported} from './scanner.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={shield:'M12 3 4.5 6v6c0 4.5 7.5 9 7.5 9s7.5-4.5 7.5-9V6L12 3Z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',repo:'M4 4h13a2 2 0 0 1 2 2v15H6a3 3 0 0 1-3-3V6a2 2 0 0 1 2-2Z M3 17h16 M7 4v9 M14 18v3',bug:'M8 3l2 3m6-3-2 3 M7 10h10v6a5 5 0 0 1-10 0v-6Z M9 10V8a3 3 0 0 1 6 0v2 M3 12h4m10 0h4 M3 18h4m10 0h4 M12 10v11',box:'m12 3 9 5v9l-9 5-9-5V8l9-5Z M3 8l9 5 9-5 M12 13v9 M7 5.8l9 5',scan:'M8 3H3v5m13-5h5v5 M3 16v5h5m13-5v5h-5 M7 12h10 M12 7v10',chart:'M4 3v17h17 M8 15v-4m5 4V6m5 9V9',settings:'M10 3h4l1 3 3 1 3 2-2 3 1 3-3 2-1 4h-4l-1-3-3-1-3-2 2-3-1-3 3-2 1-4Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',help:'M9 9a3 3 0 1 1 4 3c-1 1-1 1-1 3 M12 18h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',chevron:'m9 5 7 7-7 7',down:'m7 10 5 5 5-5',plus:'M12 5v14 M5 12h14',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',download:'M12 3v12m-5-5 5 5 5-5 M4 16v5h16v-5',branch:'M6 3v12a3 3 0 1 0 3 3 M18 6v2c0 4-12 2-12 7 M9 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z M21 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',check:'m5 12 4 4L19 6',cross:'m6 6 12 12 M6 18 18 6',arrow:'M4 12h16m-6-6 6 6-6 6',external:'M14 3h7v7 M21 3 11 13 M10 3H3v18h18v-7',code:'m8 6-6 6 6 6m8-12 6 6-6 6 M14 3l-4 18',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',upload:'M12 16V3m-5 5 5-5 5 5 M4 15v6h16v-6',file:'M14 2H4v20h16V8l-6-6Z M14 2v6h6 M8 13h8m-8 4h6',folder:'M3 5h7l2 3h9v13H3V5Z',filter:'M3 5h18l-7 8v6l-4 2v-8L3 5Z',menu:'M4 6h16M4 12h16M4 18h16',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',git:'M8 3H5v18h14V8h-6V3 M8 14h8 M8 17h6',circle:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z'};
const icon=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.shield}"/></svg>`;
const badge=(s)=>`<span class="badge ${esc(s)}">${esc(s)}</span>`;
const sampleFiles=[{path:'src/api/auth.ts',content:'// Example code for scanner demonstration\nconst client_secret = "sample-value-only";\nconst result = eval(userInput);'},{path:'src/components/Preview.tsx',content:'preview.innerHTML = userContent;'},{path:'src/services/client.ts',content:'const agent = { rejectUnauthorized: false };'},{path:'src/utils/hash.ts',content:'const hash = crypto.createHash("md5");'},{path:'src/config/endpoints.ts',content:'const endpoint = "http://api.example.com/data";'}];
function demoScan(){const s=scanSource(sampleFiles);s.name='acme / storefront';s.demo=true;s.date=new Date().toISOString();s.id='sample';s.files=156;s.lines=12480;s.dependencies=[{name:'express',version:'4.17.1',latest:'4.21.2',exact:true,status:'checked',path:'package-lock.json',advisories:[{id:'EXAMPLE-001',title:'Example dependency advisory',severity:'High'}]},{name:'lodash',version:'4.17.20',latest:'4.17.21',exact:true,status:'checked',path:'package-lock.json',advisories:[{id:'EXAMPLE-002',title:'Example dependency advisory',severity:'Medium'}]},{name:'react',version:'18.3.1',latest:'19.0.0',exact:true,status:'checked',path:'package-lock.json',advisories:[]},{name:'zod',version:'3.24.1',latest:'3.24.1',exact:true,status:'checked',path:'package-lock.json',advisories:[]},{name:'lucide-react',version:'0.468.0',latest:'0.468.0',exact:true,status:'checked',path:'package-lock.json',advisories:[]}];
  s.findings.push({id:'EXAMPLE-001',uid:'demo-dep-1',severity:'High',category:'Dependencies',title:'Vulnerable version of express',path:'package-lock.json',line:42,snippet:'"express": "4.17.1"',status:'Open',why:'This is an illustrative dependency finding, not a live advisory result.',fix:'For a real scan, upload a package-lock.json. Sentinel will query OSV for the installed versions and show advisory links and reported fixes.'},{id:'EXAMPLE-002',uid:'demo-dep-2',severity:'Medium',category:'Dependencies',title:'Vulnerable version of lodash',path:'package-lock.json',line:128,snippet:'"lodash": "4.17.20"',status:'Open',why:'This is an illustrative dependency finding, not a live advisory result.',fix:'Scan a lockfile to check exact installed versions against live OSV advisories.'});return s;}
function load(){try{return JSON.parse(localStorage.getItem('sentinel-v1'))||{};}catch{return {};}}
const saved=load();let history=Array.isArray(saved.history)?saved.history:[];let policy={blockHigh:true,blockOutdated:false,...saved.policy};let scan=history[0]||demoScan();let view='Overview';let query='',severity='All severities',category='All categories',page=1;let selectedFiles=[];let scanMode='upload';let scanning=false;let toastTimer;let liveFiles=[];
function persist(){try{localStorage.setItem('sentinel-v1',JSON.stringify({history,policy}));}catch{toast('Browser storage is full. Export your report to keep a copy.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const counts=()=>Object.fromEntries(['Critical','High','Medium','Low','Unknown'].map(s=>[s,scan.findings.filter(f=>f.severity===s).length]));
const age=(date)=>{let sec=Math.max(0,(Date.now()-new Date(date))/1000);return sec<60?'Just now':sec<3600?Math.floor(sec/60)+' min ago':sec<86400?Math.floor(sec/3600)+' hr ago':new Date(date).toLocaleDateString('en-GB');};
const checked=()=>scan.dependencies.filter(d=>d.status==='checked').length;
const outdated=()=>scan.dependencies.filter(isOutdated).length;
const openCount=()=>scan.findings.length;
function render(){
  $('#app').innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('shield',23)}</div><span>sentinel<span style="color:#9270ef">.</span></span></div><div class="workspace"><div class="ws-icon">${icon('code',15)}</div><div><strong>My workspace</strong>Personal workspace</div><span style="margin-left:auto">${icon('down',12)}</span></div><div class="label">WORKSPACE</div><nav class="nav">${[['Overview','grid'],['Repositories','repo'],['Vulnerabilities','bug'],['Dependencies','box'],['Scan history','scan'],['Reports','chart']].map(([name,i])=>`<button data-nav="${name}" class="${view===name?'active':''}">${icon(i,17)}<span>${name}</span>${name==='Vulnerabilities'?`<b class="count">${openCount()}</b>`:''}</button>`).join('')}</nav><div class="nav-divider"></div><div class="label">CONFIGURATION</div><nav class="nav"><button data-nav="Settings" class="${view==='Settings'?'active':''}">${icon('settings',17)}<span>Settings</span></button></nav><div class="sidebar-bottom"><nav class="nav"><button data-action="help">${icon('help',17)}<span>Help & documentation</span></button></nav><div class="plan">${icon('shield',18)}<strong>A safer path to production</strong><p>Catch risks early.<br>Ship with more confidence.</p></div><div class="profile"><div class="avatar">JS</div><div><strong>Jim’s workspace</strong>Local scanning</div><span style="margin-left:auto">${icon('down',12)}</span></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumbs"><button class="iconbtn mobilemenu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><span>Workspace</span>${icon('chevron',11)}<span>${view}</span></div><div class="topright"><a href="#" data-action="help">${icon('file',13)}Documentation ${icon('external',11)}</a><span style="height:18px;width:1px;background:#eee"></span><button class="iconbtn notif" data-action="activity" aria-label="Recent activity">${icon('bell',17)}</button><div class="avatar" style="width:27px;height:27px;font-size:9px">JS</div></div></header><main class="content">${pageContent()}</main></div></div>`;
  bind();
}
function heading(title,description,buttons=true){return `<div class="pagehead"><div><h1>${title}</h1><p>${description}</p></div>${buttons?`<div class="actions"><button data-action="export">${icon('download',14)}Export report</button><button class="primary" data-action="new-scan">${icon('plus',15)}New scan</button></div>`:''}</div>`;}
function projectbar(){return `<div class="projectbar"><div class="project-left"><button class="projectselect" data-action="choose-project">${icon('repo',14)}<span>${esc(scan.name)}</span>${icon('down',12)}</button><span class="branch">${icon('branch',11)} ${scan.demo?'main':'local files'}</span>${scan.demo?'<span class="demo-pill">DEMO DATA</span>':''}</div><div class="scan-age"><span class="green-dot"></span>${scan.demo?'Sample scan · explore the workspace':'Last scanned '+age(scan.date)}</div></div>`;}
function stats(){const c=counts();return `<section class="stats" aria-label="Scan statistics">${[
  ['Total vulnerabilities',openCount(),'shield',`${c.Critical+c.High} high-priority findings`,`${c.Critical+c.High?'High':'good'}`,c.Critical+c.High?'Needs review':'No blockers'],
  ['Critical issues',c.Critical,'bug',c.Critical?'Resolve before production':'No critical patterns detected','Critical',''],
  ['Outdated dependencies',outdated(),'box',`${scan.dependencies.length} packages in this scan`,'',''],
  ['Files scanned',scan.files.toLocaleString(),'code',scan.lines.toLocaleString()+' lines of code reviewed','','']
].map(([label,value,i,note,b,btxt])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(i,15)}</span></div><div class="stat-main"><span class="stat-number">${value}</span>${btxt?badge(b).replace(`>${b}<`,`>${btxt}<`):''}</div><div class="stat-note">${i==='code'?icon('check',11):i==='box'?icon('clock',11):''}${note}</div></div>`).join('')}</section>`;}
function breakdown(){const c=counts();const colors=['#e5747d','#e5a56b','#dfca79','#8ba9d0','#aaa0be'];const total=openCount();let offset=0;const arcs=Object.entries(c).map(([s,n],i)=>{let percent=total?n/total*100:0;let html=`<circle cx="80" cy="80" r="62" fill="none" stroke="${colors[i]}" stroke-width="15" pathLength="100" stroke-dasharray="${Math.max(0,percent-(n?1.6:0))} 100" stroke-dashoffset="${-offset}"/>`;offset+=percent;return html;}).join('');return `<section class="panel"><div class="panel-head"><div><h2>Vulnerability breakdown</h2><div class="sub">A clear view of your security posture</div></div><span class="tag">Current scan</span></div><div class="trendbody"><div class="ring"><svg viewBox="0 0 160 160"><circle cx="80" cy="80" r="62" fill="none" stroke="#f3eff8" stroke-width="15"/>${arcs}</svg><div class="ring-center"><strong>${total}</strong><span>Total findings</span></div></div><div class="legend">${Object.entries(c).filter(([s,n])=>s!=='Unknown'||n).map(([s,n])=>`<div class="legend-item"><div class="legend-label"><span class="legend-dot" style="background:${colors[['Critical','High','Medium','Low','Unknown'].indexOf(s)]}"></span>${s}</div><strong>${n.toString().padStart(2,'0')}</strong></div>`).join('')}</div></div><div class="trend-foot"><span>${icon('shield',12)} Prioritize critical and high severity issues</span><button class="linkbtn" data-nav="Vulnerabilities">View findings ${icon('arrow',12)}</button></div></section>`;}
function gatePanel(){const gate=releaseGate(scan,policy),c=counts();const rows=[['No critical vulnerabilities',c.Critical===0,c.Critical+' found'],['No high-severity vulnerabilities',!policy.blockHigh||c.High===0,policy.blockHigh?c.High+' found':'Optional'],['Dependency advisory checks',checked()===scan.dependencies.length,scan.dependencies.length?checked()+'/'+scan.dependencies.length+' checked':'No packages'],['Source checks completed',scan.files>0&&!scan.warnings.length,scan.files+' files']];return `<section class="panel gate"><div class="panel-head"><h2>Release readiness</h2><span class="gate-badge" style="${gate.state==='Checks passed'?'color:#4d9c82;background:#edf7f1':''}">${icon(gate.state==='Checks passed'?'check':'lock',11)}${gate.state}</span></div><p class="gate-text">${esc(gate.reason)}</p><div class="checks">${rows.map(([name,pass,val])=>`<div class="check"><span>${icon(pass?'check':'cross',12).replace('stroke="currentColor"',`stroke="${pass?'#60a589':'#dd7d83'}"`)}${name}</span><span class="check-val">${val}</span></div>`).join('')}</div><div class="gatefooter"><span>${icon('shield',11)} Policy: ${policy.blockHigh?'Standard protection':'Custom protection'}</span><button class="linkbtn" data-nav="Settings">Manage policy ${icon('arrow',11)}</button></div></section>`;}
function filteredFindings(){const order=['Critical','High','Medium','Low','Unknown'];return scan.findings.filter(f=>(severity==='All severities'||f.severity===severity)&&(category==='All categories'||f.category===category)&&`${f.title} ${f.path} ${f.id}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>order.indexOf(a.severity)-order.indexOf(b.severity));}
function findingsPanel(limit=5){const filtered=filteredFindings();const pages=Math.max(1,Math.ceil(filtered.length/limit));page=Math.min(page,pages);const visible=filtered.slice((page-1)*limit,page*limit);return `<section class="panel findings"><div class="panel-head"><div class="sectiontitle"><h2>${view==='Overview'?'Priority findings':'All findings'}</h2><span class="numbadge">${openCount()}</span></div><span class="muted small">${scan.demo?'Illustrative findings':'Requires review'}</span></div><div class="tabletools"><div class="search">${icon('search',13)}<input id="search" placeholder="Search vulnerabilities..." value="${esc(query)}" aria-label="Search vulnerabilities"></div><select id="severity" aria-label="Filter by severity">${['All severities','Critical','High','Medium','Low','Unknown'].map(s=>`<option ${s===severity?'selected':''}>${s}</option>`).join('')}</select><select id="category" aria-label="Filter by category">${['All categories','Code security','Dependencies','Secrets'].map(s=>`<option ${s===category?'selected':''}>${s}</option>`).join('')}</select><span class="spacer"></span><span class="label-right">Sorted by severity ${icon('down',11)}</span></div><div class="tablewrap"><table><thead><tr><th style="width:105px">Severity</th><th>Vulnerability</th><th>Location</th><th class="hide-md">Category</th><th>Status</th><th></th></tr></thead><tbody>${visible.map(f=>`<tr class="finding-row" data-finding="${esc(f.uid)}" tabindex="0" role="button" aria-label="Review ${esc(f.title)}"><td>${badge(f.severity)}</td><td><div class="finding-title">${esc(f.title)}</div><div class="finding-meta">${icon(f.category==='Dependencies'?'box':'code',10)}${esc(f.id)}</div></td><td><span class="path" title="${esc(f.path)}">${esc(f.path)}</span><span style="font-size:9px;color:#b3acbb">Line ${f.line}</span></td><td class="hide-md" style="font-size:10px">${f.category}</td><td><span class="status">Open</span></td><td>${icon('chevron',12)}</td></tr>`).join('')}</tbody></table>${!visible.length?`<div class="empty">${icon('shield',28)}<h3>${scan.findings.length?'No matching findings':'No findings in these checks'}</h3><p>${scan.findings.length?'Try changing your search or filters.':'Continue with your test suite and code review before production.'}</p></div>`:''}</div><div class="tablefooter"><span>Showing ${visible.length?(page-1)*limit+1:0}–${Math.min(page*limit,filtered.length)} of ${filtered.length} findings</span><div class="pagination"><button data-page="${page-1}" ${page===1?'disabled':''} aria-label="Previous page">${icon('chevron',10).replace('<svg','<svg style="transform:rotate(180deg)"')}</button><button class="selected">${page}</button><button data-page="${page+1}" ${page===pages?'disabled':''} aria-label="Next page">${icon('chevron',10)}</button></div></div></section>`;}
function dependencyHealth(){const n=scan.dependencies.length;const vulnerable=scan.dependencies.filter(d=>d.advisories.length).length;const out=scan.dependencies.filter(d=>isOutdated(d)&&!d.advisories.length).length;const okay=scan.dependencies.filter(d=>d.status==='checked'&&!d.advisories.length&&!isOutdated(d)).length;return `<section class="panel"><div class="panel-head"><h2>Dependency health</h2><span class="tag">npm</span></div><div class="healthbody"><div class="healthbar">${[[okay,'#8bbba4'],[out,'#e1c57e'],[vulnerable,'#dc8c91'],[Math.max(0,n-okay-out-vulnerable),'#ccc6d7']].filter(([v])=>v).map(([v,color])=>`<span style="width:${v/n*100}%;background:${color}"></span>`).join('')||'<span style="width:100%;background:#ede9f3"></span>'}</div><div class="healthlegend">${[[okay,'Current','#8bbba4'],[out,'Outdated','#e1c57e'],[vulnerable,'Vulnerable','#dc8c91']].map(([num,s,color])=>`<span><b class="legend-dot" style="background:${color}"></b>${s}<b style="font-weight:550;color:#73687f">${num}</b></span>`).join('')}</div></div><div class="healthfoot"><span>${n} packages · ${scan.demo?'Sample versions':checked()+' checked against OSV'}</span><button class="linkbtn" data-nav="Dependencies">View dependencies ${icon('arrow',11)}</button></div></section>`;}
function activityPanel(){const items=scan.demo?[{name:'storefront',date:scan.date,files:156,findings:scan.findings,demo:true}]:history.slice(0,2);return `<section class="panel"><div class="panel-head"><h2>Recent activity</h2><button class="linkbtn" data-nav="Scan history">View all ${icon('arrow',11)}</button></div><div class="activity">${items.map(s=>`<div class="activityitem"><span class="activityicon">${icon('scan',12)}</span><div><strong>${s.demo?'Sample scan ready to explore':'Scan completed · '+esc(s.name)}</strong><p>${s.files} files scanned · ${s.findings.length} findings ${s.demo?'· demo data':''}</p></div><span class="activitytime">${s.demo?'Demo':age(s.date)}</span></div>`).join('')}</div>${!scan.demo&&items.length===1?'<p class="no-history">Your next scan will appear here. Compare results as you fix issues.</p>':''}</section>`;}
function footer(){return `<footer class="footer"><span>${icon('shield',11)} Code stays in your browser</span><span>Sentinel · Built for safer releases ${icon('spark',10)}</span></footer>`;}
function pageContent(){
  if(view==='Overview')return heading('Security overview','Your code. Your dependencies. A clearer path to production.')+projectbar()+stats()+`<div class="middle">${breakdown()}${gatePanel()}</div>`+findingsPanel()+`<div class="bottomgrid">${dependencyHealth()}${activityPanel()}</div>`+footer();
  if(view==='Vulnerabilities')return heading('Vulnerabilities','Understand the risk. Review the evidence. Plan your next fix.')+projectbar()+findingsPanel(10)+footer();
  if(view==='Dependencies')return dependenciesPage();
  if(view==='Settings')return settingsPage();
  if(view==='Repositories')return repositoriesPage();
  if(view==='Scan history')return historyPage();
  if(view==='Reports')return reportsPage();
}
function dependenciesPage(){return heading('Dependencies','Inspect installed packages, known advisories, and available updates.')+projectbar()+(scan.demo?'<div class="notice">These are sample dependency versions. Run a scan with your package-lock.json for live advisory and version checks.</div>':'')+`<div class="bottomgrid" style="margin-bottom:24px">${dependencyHealth()}${gatePanel()}</div><div class="panel"><div class="panel-head"><h2>Package inventory <span class="numbadge">${scan.dependencies.length}</span></h2><span class="muted small">Exact versions produce reliable matches</span></div><div class="tablewrap"><table><thead><tr><th>Package</th><th>Installed</th><th>Latest</th><th>Advisories</th><th>Status</th></tr></thead><tbody>${scan.dependencies.map(d=>`<tr><td style="color:#60546e;font-weight:550">${icon('box',13)} ${esc(d.name)}</td><td class="mono">${esc(d.version)}</td><td class="mono">${esc(d.latest||'Unavailable')}</td><td>${d.advisories.length?`<button class="linkbtn" data-package="${esc(d.name)}">${d.advisories.length} ${scan.demo?'sample findings':'advisories'} ${icon('arrow',11)}</button>`:'—'}</td><td>${d.status!=='checked'?badge('Unknown').replace('Unknown</span>',esc(d.status==='unresolved'?'Lockfile needed':d.status)+'</span>'):d.advisories.length?badge('High').replace('High</span>','Vulnerable</span>'):isOutdated(d)?badge('Medium').replace('Medium</span>','Update available</span>'):badge('good').replace('good</span>','No advisories</span>')}</td></tr>`).join('')}</tbody></table>${!scan.dependencies.length?'<div class="empty">No npm packages found. Include a package-lock.json in your next scan.</div>':''}</div></div><div class="privacy">${icon('help',15)}Latest versions may include breaking changes. Review release notes and run tests before upgrading. Ranged versions in package.json need a lockfile to verify the installed version.</div>`+footer();}
function repositoriesPage(){const scans=[...new Map(history.map(s=>[s.name,s])).values()];if(!scans.length)scans.push(scan);return heading('Repositories','Keep your projects in view. Scan local code before your next release.')+`<div class="notice">Local file scanning is ready. Direct GitHub connections, automatic pull-request checks, and enforced CI gates require a backend integration.</div><div class="panel"><div class="panel-head"><h2>Your projects</h2><span class="tag">${scans.length} project${scans.length===1?'':'s'}</span></div><div class="pagepanel">${scans.map(s=>`<div class="repo-card">${icon('repo',22)}<div><h3>${esc(s.name)} ${s.demo?'<span class="demo-pill">DEMO</span>':''}</h3><p>${s.files} files · ${s.dependencies.length} packages · ${s.demo?'Sample scan':age(s.date)}</p></div><div class="actions">${badge(releaseGate(s,policy).state==='Checks passed'?'good':'High').replace(/>(good|High)<\/span>/,'>'+releaseGate(s,policy).state+'</span>')}<button data-scan-id="${esc(s.id)}">View results ${icon('arrow',12)}</button></div></div>`).join('')}</div></div>`+footer();}
function historyPage(){return heading('Scan history','A record of your checks, findings, and release decisions.')+`<div class="panel"><div class="panel-head"><h2>Recent scans</h2><span class="muted small">Last 10 scans stored in this browser</span></div>${!history.length?`<div class="empty">${icon('clock',30)}<h3>Your scan history starts here</h3><p>Run a scan to track your project’s security checks over time.</p><button class="primary" data-action="new-scan">${icon('scan',14)}Scan your code</button></div>`:`<div class="tablewrap"><table><thead><tr><th>Project</th><th>Scanned</th><th>Files</th><th>Findings</th><th>Result</th><th></th></tr></thead><tbody>${history.map(s=>`<tr><td>${esc(s.name)}</td><td>${new Date(s.date).toLocaleString('en-GB')}</td><td>${s.files}</td><td>${s.findings.length}</td><td>${esc(releaseGate(s,policy).state)}</td><td><button class="linkbtn" data-scan-id="${esc(s.id)}">Open report ${icon('arrow',12)}</button></td></tr>`).join('')}</tbody></table></div>`}</div>`+footer();}
function reportsPage(){const gate=releaseGate(scan,policy);return heading('Reports','Take your findings into code review and release planning.')+projectbar()+`<div class="bottomgrid"><div class="panel"><div class="panel-head"><h2>Security assessment</h2><span class="tag">JSON</span></div><div class="pagepanel"><div class="detail-section"><h3>${esc(scan.name)}</h3><p>${scan.files} source files, ${scan.dependencies.length} dependencies, and ${scan.findings.length} findings. Includes remediation guidance, check coverage, and your policy result.</p></div><button class="primary" data-action="export">${icon('download',14)}Download JSON report</button><button style="margin-left:8px" data-action="export-text">${icon('file',14)}Text summary</button></div></div><div>${gatePanel()}</div></div><div class="privacy">${icon('lock',15)}Reports contain file paths and redacted finding excerpts. Source code stays in your browser. Downloaded reports are managed by you.</div>`+footer();}
function settingsPage(){return heading('Workspace settings','Set the rules for your next release.',false)+`<div class="panel"><div class="panel-head"><h2>Release policy</h2><span class="tag">Applies to all local scans</span></div><div class="pagepanel"><div class="policy-row"><div><h3>Block critical vulnerabilities</h3><p>Always require review of critical security findings.</p></div><span class="badge good">Always enabled</span></div><div class="policy-row"><div><h3>Block high-severity vulnerabilities</h3><p>Require review of high-severity findings before checks can pass.</p></div><button class="toggle ${policy.blockHigh?'on':''}" data-toggle="blockHigh" role="switch" aria-checked="${policy.blockHigh}" aria-label="Block high severity"></button></div><div class="policy-row"><div><h3>Require current dependencies</h3><p>Block when a newer stable npm version is available. Major upgrades may need migration work.</p></div><button class="toggle ${policy.blockOutdated?'on':''}" data-toggle="blockOutdated" role="switch" aria-checked="${policy.blockOutdated}" aria-label="Require current dependencies"></button></div><div class="policy-row"><div><h3>Flag incomplete checks</h3><p>Unresolved versions, unavailable advisories, and unreadable files prevent a passing result.</p></div><span class="badge good">Always enabled</span></div></div></div><div class="notice" style="margin-top:20px">These rules evaluate the local scan report. They do not enforce deployment permissions or replace tests, full static analysis, or manual review.</div><div class="panel"><div class="panel-head"><h2>Data & privacy</h2></div><div class="pagepanel"><div class="policy-row"><div><h3>Browser-local scan history</h3><p>The last 10 reports are stored on this device. Source files are kept in memory only.</p></div><button data-action="clear-history">Clear history</button></div><div class="detail-section"><p>Dependency checks send only package names and versions to OSV and npm. Full source files are never uploaded by this app. External APIs must be available to complete dependency checks.</p></div></div></div>`+footer();}
function navigate(name){view=name;query='';severity='All severities';category='All categories';page=1;render();window.scrollTo(0,0);}
function bind(){
  document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(el.dataset.nav));
  document.querySelectorAll('[data-action]').forEach(el=>el.onclick=e=>{e.preventDefault();actions[el.dataset.action]?.();});
  document.querySelectorAll('[data-finding]').forEach(el=>{el.onclick=()=>openFinding(el.dataset.finding);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openFinding(el.dataset.finding);}};});
  document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page=Number(el.dataset.page);refreshFindings();});
  document.querySelectorAll('[data-scan-id]').forEach(el=>el.onclick=()=>{scan=history.find(s=>s.id===el.dataset.scanId)||demoScan();navigate('Overview');});
  document.querySelectorAll('[data-toggle]').forEach(el=>el.onclick=()=>{policy[el.dataset.toggle]=!policy[el.dataset.toggle];persist();render();toast('Release policy updated.');});
  document.querySelectorAll('[data-package]').forEach(el=>el.onclick=()=>{navigate('Vulnerabilities');category='Dependencies';query=el.dataset.package;refreshFindings();});
  if($('#search'))$('#search').oninput=e=>{query=e.target.value;page=1;refreshFindings(true);};
  if($('#severity'))$('#severity').onchange=e=>{severity=e.target.value;page=1;refreshFindings();};
  if($('#category'))$('#category').onchange=e=>{category=e.target.value;page=1;refreshFindings();};
}
function refreshFindings(focus=false){const start=$('#search')?.selectionStart;$('.findings').outerHTML=findingsPanel(view==='Overview'?5:10);bind();if(focus){$('#search').focus();$('#search').setSelectionRange(start,start);}}
let returnFocus,modalKeyHandler;
function closeModal(){if(scanning)return;$('#overlay').innerHTML='';document.body.style.overflow='';document.removeEventListener('keydown',modalKeyHandler);returnFocus?.focus();}
function modal(content){returnFocus=document.activeElement;$('#overlay').innerHTML=`<div class="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${content}</section></div>`;document.body.style.overflow='hidden';$('#overlay .backdrop').onclick=e=>{if(e.target.classList.contains('backdrop'))closeModal();};$('#overlay').querySelectorAll('[data-close]').forEach(el=>el.onclick=closeModal);document.removeEventListener('keydown',modalKeyHandler);modalKeyHandler=e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusable=[...$('#overlay').querySelectorAll('button:not(:disabled),input,textarea,select,a[href]')].filter(el=>el.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',modalKeyHandler);$('#overlay button')?.focus();}
const modalHead=(title,sub)=>`<div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${sub}</p></div><button class="iconbtn" data-close aria-label="Close dialog">${icon('cross',17)}</button></div>`;
function openFinding(uid){const f=scan.findings.find(f=>f.uid===uid);if(!f)return;modal(`${modalHead('Review finding',esc(f.id)+' · '+esc(f.category))}<div class="modal-body">${badge(f.severity)}<h2 style="font-size:20px;margin-top:14px">${esc(f.title)}</h2><p class="detail-path">${icon('file',13)} ${esc(f.path)}:${f.line}</p><div class="codeblock">${esc(f.snippet)}</div><div class="detail-section"><h3>Why this matters</h3><p>${esc(f.why)}</p></div><div class="detail-section"><h3>Recommended remediation</h3><p>${esc(f.fix)}</p></div>${scan.demo?'<div class="notice">You are viewing sample data. Run a scan to inspect your own code.</div>':''}${f.url?`<a href="${esc(f.url)}" target="_blank" rel="noopener">Read OSV advisory ${icon('external',12)}</a>`:'<p class="muted small">Pattern-based finding · Verify context before making changes.</p>'}</div><div class="modal-foot"><button data-close>Close</button><button class="primary" id="copy-finding">${icon('file',13)}Copy finding</button></div>`);$('#copy-finding').onclick=async()=>{const text=`${f.severity}: ${f.title}\n${f.path}:${f.line}\n\n${f.why}\n\n${f.fix}`;try{await navigator.clipboard.writeText(text);toast('Finding copied.');}catch{toast('Clipboard unavailable. Export a report instead.');}};}
function openScan(){selectedFiles=[];scanMode='upload';scanForm();}
function scanForm(){modal(`${modalHead('Start a new scan','Find risky code patterns, potential secrets, and vulnerable npm packages.')}<div class="modal-body"><div class="formtabs"><button id="upload-tab" class="${scanMode==='upload'?'active':''}">${icon('folder',14)}Upload code</button><button id="paste-tab" class="${scanMode==='paste'?'active':''}">${icon('code',14)}Paste code</button></div><div class="field" style="margin-top:0;margin-bottom:17px"><label for="project-name">Project name</label><input id="project-name" placeholder="e.g. storefront-api" maxlength="80" value="${esc(selectedFiles[0]?.path.split('/')[0]||'')}"></div>${scanMode==='upload'?`<div class="dropzone" id="dropzone">${icon('upload',24)}<h3>Bring your code into focus</h3><p>Choose a project folder or source files.<br>Include package-lock.json for exact dependency checks.</p><div class="drop-actions"><button id="select-folder">${icon('folder',14)}Choose folder</button><button id="select-files">${icon('file',14)}Choose files</button></div><input id="folder-input" type="file" webkitdirectory multiple hidden><input id="file-input" type="file" multiple hidden></div><div id="file-selection">${fileSelection()}</div>`:`<div class="field"><label for="file-name">File name</label><input id="file-name" value="app.js" maxlength="200"></div><div class="field"><label for="source">Source code</label><textarea id="source" placeholder="Paste JavaScript, TypeScript, Python, or another supported source file…" spellcheck="false"></textarea></div>`}<div class="privacy">${icon('lock',15)}<span>Source stays in your browser. Package names and versions are sent to OSV and npm for live checks. Generated folders are skipped. Limit: 2,000 files, 2 MB per file, 30 MB total.</span></div><div id="scan-progress"></div></div><div class="modal-foot"><button data-close>Cancel</button><button class="primary" id="run-scan">${icon('scan',15)}Run scan</button></div>`);
  $('#upload-tab').onclick=()=>{scanMode='upload';scanForm();};$('#paste-tab').onclick=()=>{scanMode='paste';scanForm();};$('#run-scan').onclick=runScan;
  if(scanMode==='upload'){$('#select-folder').onclick=()=>$('#folder-input').click();$('#select-files').onclick=()=>$('#file-input').click();for(const id of ['folder-input','file-input'])$('#'+id).onchange=e=>selectFiles([...e.target.files]);$('#dropzone').ondragover=e=>{e.preventDefault();$('#dropzone').style.borderColor='#7559ee';};$('#dropzone').ondragleave=()=>$('#dropzone').style.borderColor='';$('#dropzone').ondrop=e=>{e.preventDefault();$('#dropzone').style.borderColor='';selectFiles([...e.dataTransfer.files]);};}
}
function fileSelection(){return selectedFiles.length?`<div class="selected-files"><strong>${selectedFiles.length} files selected</strong><br>${selectedFiles.slice(0,5).map(f=>esc(f.path)).join('<br>')}${selectedFiles.length>5?'<br>+ '+(selectedFiles.length-5)+' more':''}</div>`:'';}
function selectFiles(files){selectedFiles=files.map(f=>({file:f,path:f.webkitRelativePath||f.name}));$('#file-selection').innerHTML=fileSelection();if(!$('#project-name').value&&selectedFiles.length)$('#project-name').value=selectedFiles[0].path.includes('/')?selectedFiles[0].path.split('/')[0]:'My project';}
function setProgress(text,pct){$('#scan-progress').innerHTML=`<div class="progressbar"><span style="width:${pct}%"></span></div><p class="progress-message">${esc(text)}</p>`;}
async function runScan(){
  if(scanning)return;const name=$('#project-name').value.trim()||'My project';let inputs=[];const warnings=[];
  if(scanMode==='paste'){const content=$('#source').value;const path=$('#file-name').value.trim()||'app.js';if(!content.trim()){toast('Paste some code to scan.');return;}if(!supported.test(path)){toast('Use a supported source file extension, such as .js, .ts, or .py.');return;}if(content.length>2*1024*1024){toast('Pasted source exceeds the 2 MB limit.');return;}inputs=[{path,content}];}
  else {if(!selectedFiles.length){toast('Choose source files or a project folder first.');return;}const eligible=selectedFiles.filter(f=>supported.test(f.path)&&!/(?:^|\/)(?:node_modules|\.git|dist|build|vendor|coverage|\.next)\//.test(f.path));if(!eligible.length){toast('No supported source files found. Choose a folder containing source code.');return;}
    if(eligible.length>2000)warnings.push('Only the first 2,000 supported files were scanned.');let bytes=0;
    for(const f of eligible.slice(0,2000)){if(f.file.size>2*1024*1024){warnings.push('Skipped oversized file: '+f.path);continue;}if(bytes+f.file.size>30*1024*1024){warnings.push('Skipped file at 30 MB total limit: '+f.path);continue;}bytes+=f.file.size;inputs.push(f);}
  }
  scanning=true;$('#run-scan').disabled=true;$('#overlay').querySelectorAll('button,input,textarea').forEach(el=>el.disabled=true);setProgress('Reading source files…',10);
  try{
    const files=[];for(const f of inputs){try{const content=f.content??await f.file.text();if(content.includes('\0')){warnings.push('Skipped binary file: '+f.path);continue;}files.push({path:f.path,content});}catch{warnings.push('Could not read '+f.path);}}
    if(!files.length)throw new Error('No readable files remained. Choose supported text files and try again.');
    setProgress('Checking source patterns and potential secrets…',25);await new Promise(r=>setTimeout(r,30));
    const result=scanSource(files);result.warnings.push(...warnings);result.name=name;result.id=crypto.randomUUID();result.date=new Date().toISOString();result.demo=false;
    setProgress('Querying live dependency advisories…',40);
    const findings=await scanDependencies(result.dependencies,(done,total)=>setProgress(`Checking npm dependencies: ${done} of ${total}`,40+done/Math.max(total,1)*55));result.findings.push(...findings);
    if(result.dependencies.length>300)result.warnings.push('Only the first 300 package versions were checked.');
    result.duration='Browser scan';liveFiles=files;scan=result;history=[result,...history].slice(0,10);persist();scanning=false;closeModal();navigate('Overview');toast(`Scan completed: ${result.files} files, ${result.findings.length} findings.${result.dependencies.some(d=>d.status!=='checked')?' Some dependency checks are incomplete.':''}`);
  }catch(error){scanning=false;$('#overlay').querySelectorAll('button,input,textarea').forEach(el=>el.disabled=false);$('#scan-progress').innerHTML=`<div class="notice">${esc(error.message||'Scan failed. Please try again.')}</div>`;}
}
function download(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportReport(text=false){const slug=scan.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase();const gate=releaseGate(scan,policy);const limitations=['Pattern-based source review; no data-flow analysis, application execution, test execution, or guarantee of bug-free code.','npm advisories from OSV; latest versions from npm. Versions with ranges are not treated as installed versions.','This is a report policy check, not an enforced CI deployment gate.'];if(text){download(`sentinel-${slug}.txt`,`SENTINEL SECURITY REPORT${scan.demo?' — DEMO DATA':''}\nProject: ${scan.name}\nDate: ${scan.date}\nResult: ${gate.state}\n${gate.reason}\n\nFiles: ${scan.files}\nDependencies: ${scan.dependencies.length}\nFindings: ${scan.findings.length}\n\n${scan.findings.map(f=>`${f.severity}: ${f.title}\n${f.path}:${f.line}\n${f.fix}`).join('\n\n')}\n\nWarnings:\n${scan.warnings.join('\n')||'None'}\n\nLimitations:\n${limitations.join('\n')}`,'text/plain');}else download(`sentinel-${slug}.json`,JSON.stringify({app:'Sentinel',schemaVersion:1,...scan,policy,releaseGate:gate,limitations},null,2),'application/json');toast('Report downloaded.');}
function help(){modal(`${modalHead('A guide to safer releases','What Sentinel checks, and how to use your results.')}<div class="modal-body doc-list"><div><strong>01 · Scan your project</strong>Choose source files or a folder. Supported patterns cover JavaScript, TypeScript, Python, and common source/configuration formats. Generated directories are skipped. Only npm dependencies are checked; other ecosystems need a separate scanner.</div><div><strong>02 · Include your lockfile</strong>package-lock.json v1–v3 provides exact installed npm versions, including transitive packages. Exact versions in package.json also work. Ranged versions require a lockfile. Up to 300 unique package versions are checked per scan.</div><div><strong>03 · Review findings in context</strong>Source checks identify patterns, including dynamic evaluation, unsafe HTML, disabled TLS, and likely secrets. They may produce false positives. Inspect each finding and verify input paths before applying a fix.</div><div><strong>04 · Check dependencies live</strong>Sentinel queries <a href="https://osv.dev" target="_blank" rel="noopener">OSV</a> for advisories and <a href="https://www.npmjs.com" target="_blank" rel="noopener">npm</a> for latest versions. Only names and versions leave the browser. Network failures are shown as incomplete checks.</div><div><strong>05 · Make a release decision</strong>The release policy evaluates this report only. Run your application’s tests, full SAST, and code review before deploying. CI enforcement, GitHub connections, and automatic fixes are not included in this version.</div></div><div class="modal-foot"><button class="primary" data-close>Got it</button></div>`);}
const actions={
  'new-scan':openScan,'export':()=>exportReport(),'export-text':()=>exportReport(true),'help':help,
  'menu':()=>$('.sidebar').classList.toggle('mobile-open'),
  'activity':()=>navigate('Scan history'),
  'choose-project':()=>navigate('Repositories'),
  'clear-history':()=>modal(`${modalHead('Clear scan history?','This removes saved reports from this browser. Export any report you want to keep.')}<div class="modal-foot"><button data-close>Cancel</button><button class="primary" id="confirm-clear">Clear history</button></div>`)
};
document.addEventListener('click',e=>{if(e.target.closest('#confirm-clear')){history=[];liveFiles=[];scan=demoScan();persist();closeModal();render();toast('Local scan history cleared.');}});
render();
